    var ses = arg_ses;
    _ = &ses;
    var arg = arg_arg;
    _ = &arg;
    var arg1 = arg_arg1;
    _ = &arg1;
    var arg2 = arg_arg2;
    _ = &arg2;
    var arg3 = arg_arg3;
    _ = &arg3;
    arg = sub_arg_in_braces(ses, arg, arg1, GET_ONE, (@as(c_int, 1) << @intCast(@as(c_int, 4))) | (@as(c_int, 1) << @intCast(@as(c_int, 5))));
    while (true) {
        switch (@as(c_int, arg1.*)) {
            @as(c_int, '-') => {
                {
                    const ref = &ses.*.gagline;
                    ref.* = @intFromFloat(@as(c_longdouble, @floatFromInt(ref.*)) - get_number(ses, arg1 + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 1)))))));
                }
