            },
            @as(c_int, '+') => {
                {
                    const ref = &ses.*.gagline;
                    ref.* = @intFromFloat(@as(c_longdouble, @floatFromInt(ref.*)) + get_number(ses, arg1 + @as(usize, @bitCast(@as(isize, @intCast(@as(c_int, 1)))))));
                }
                break;
            },
            @as(c_int, 0) => {
                ses.*.gagline = 1;
                break;
            },
            else => {
                ses.*.gagline = @intFromFloat(get_number(ses, arg1));
                break;
            },
        }
        break;
    }
    if (ses.*.gagline < @as(c_int, 0)) {
        ses.*.gagline = 0;
    }
    show_debug(ses, LIST_GAG, null, @as([*c]u8, @ptrCast(@constCast("\x1b[38;5;037m#DEBUG LINE GAG \x1b[38;5;164m{\x1b[38;5;188m%s\x1b[38;5;164m} \x1b[38;5;044m[\x1b[38;5;188m%d\x1b[38;5;044m]"))), arg1, ses.*.gagline);
    return ses;
}
