pub export fn line_substitute(arg_ses: [*c]struct_session, arg_arg: [*c]u8, arg_arg1: [*c]u8, arg_arg2: [*c]u8, arg_arg3: [*c]u8) [*c]struct_session {
    var ses = arg_ses;
    _ = &ses;
    var arg = arg_arg;
    _ = &arg;
    var arg1 = arg_arg1;
    _ = &arg1;
    var arg2 = arg_arg2;
    _ = &arg2;
    var arg3 = arg_arg3;
    _ = &arg3;
    var i: c_int = undefined;
    _ = &i;
    var flags: c_int = 0;
    _ = &flags;
    arg = get_arg_in_braces(ses, arg, arg1, GET_ONE);
    arg = get_arg_in_braces(ses, arg, arg2, GET_ALL);
    if (@as(c_int, arg2.*) == @as(c_int, 0)) {
        {
            i = 0;
            while (@as(c_int, substitution_table[@bitCast(@as(isize, @intCast(i)))].name.*) != 0) : (i += 1) {
                show_error(ses, LIST_COMMAND, @as([*c]u8, @ptrCast(@constCast("#SYNTAX: #LINE {SUBSTITUTE} {%s} <COMMAND>"))), substitution_table[@bitCast(@as(isize, @intCast(i)))].name);
            }
        }
        return ses;
    }
    arg = arg1;
    while (@as(c_int, arg.*) != 0) {
        arg = get_arg_in_braces(ses, arg, arg3, GET_ONE);
        {
            i = 0;
            while (@as(c_int, substitution_table[@bitCast(@as(isize, @intCast(i)))].name.*) != 0) : (i += 1) {
                if (is_abbrev(arg3, substitution_table[@bitCast(@as(isize, @intCast(i)))].name) != 0) {
                    flags |= substitution_table[@bitCast(@as(isize, @intCast(i)))].bitvector;
                }
            }
        }
        if (@as(c_int, arg.*) == COMMAND_SEPARATOR) {
            arg += 1;
        }
    }
    _ = substitute(ses, arg2, arg3, flags);
    ses = script_driver(ses, LIST_COMMAND, null, arg3);
    return ses;
}
